class CurrencyConverter:
    USD = 'USD'
    EUR = 'EUR'
    GBP = 'GBP'
    JPY = 'JPY'
    CAD = 'CAD'
    AUD = 'AUD'
    CNY = 'CNY'

    def __init__(self):
        self._rates = {
            self.USD: 1.0,
            self.EUR: 0.85,
            self.GBP: 0.72,
            self.JPY: 110.15,
            self.CAD: 1.23,
            self.AUD: 1.34,
            self.CNY: 6.40,
        }

    @property
    def rates(self):
        return self._rates

    def convert(self, amount, from_currency, to_currency):
        if from_currency == to_currency:
            return amount

        if self._is_valid_currency(from_currency) and self._is_valid_currency(to_currency):
            return self._calculate_converted_amount(amount, from_currency, to_currency)
        return False

    def _is_valid_currency(self, currency):
        return currency in self._rates

    def _calculate_converted_amount(self, amount, from_currency, to_currency):
        from_rate = self._get_rate(from_currency)
        to_rate = self._get_rate(to_currency)
        return (amount / from_rate) * to_rate

    def _get_rate(self, currency):
        return self._rates[currency]

    def get_supported_currencies(self):
        return list(self._rates.keys())

    def add_currency_rate(self, currency, rate):
        if currency in self._rates:
            return False
        self._rates[currency] = rate
        return True

    def update_currency_rate(self, currency, new_rate):
        if currency not in self._rates:
            return False
        self._rates[currency] = new_rate
        return True
